import csv
import json
import re
from copy import deepcopy
from json.encoder import encode_basestring, encode_basestring_ascii


INPUT_PANEL_MANIFEST = "/root/panel_manifest.json"
INPUT_SHIPPER_COST = "/root/shipper_cost.csv"
INPUT_CONTRACT_TERMS = "/root/contract_terms.csv"
INPUT_NETWORK_ADJUSTMENTS = "/root/network_adjustments.csv"
INPUT_LAB_CAPACITY_OVERRIDES = "/root/lab_capacity_overrides.csv"
INPUT_HOLDOUTS = "/root/holdouts.json"
INPUT_REPORT_TEMPLATE = "/root/report_template.json"
OUTPUT_REPORT = "/root/diagpanel_policy_report.json"
OUTPUT_SUMMARY = "/root/diagpanel_policy_summary.md"


class Currency(float):
    """Float marker serialized with exactly two decimal places."""


def currency(value):
    return Currency(round(float(value), 2))


class CurrencyEncoder(json.JSONEncoder):
    def iterencode(self, o, _one_shot=False):
        if self.check_circular:
            markers = {}
        else:
            markers = None
        if self.ensure_ascii:
            _encoder = encode_basestring_ascii
        else:
            _encoder = encode_basestring

        def floatstr(value, allow_nan=self.allow_nan):
            if isinstance(value, Currency):
                return f"{float(value):.2f}"
            if value != value:
                text = "NaN"
            elif value == float("inf"):
                text = "Infinity"
            elif value == float("-inf"):
                text = "-Infinity"
            else:
                return float.__repr__(value)
            if not allow_nan:
                raise ValueError(
                    "Out of range float values are not JSON compliant: " + repr(value)
                )
            return text

        _iterencode = json.encoder._make_iterencode(
            markers,
            self.default,
            _encoder,
            self.indent,
            floatstr,
            self.key_separator,
            self.item_separator,
            self.sort_keys,
            self.skipkeys,
            _one_shot,
        )
        return _iterencode(o, 0)


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def load_csv(path):
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def as_panel_list(manifest):
    if isinstance(manifest, list):
        return manifest
    panels = []
    for cluster in manifest.get("service_clusters", []):
        panels.extend(cluster.get("panels", []))
    return panels


def as_holdout_list(holdouts):
    if isinstance(holdouts, list):
        return holdouts
    return holdouts.get("holdouts", [])


def is_numeric_string(value):
    return bool(re.fullmatch(r"[+-]?\d+(?:\.\d+)?", str(value).strip()))


def effective_key(value):
    text = str(value).strip()
    if is_numeric_string(text):
        return (1, float(text))
    return (0, text)


def is_not_blank(value):
    return value is not None and str(value).strip() != ""


def main():
    manifest = load_json(INPUT_PANEL_MANIFEST)
    shipper_rows = load_csv(INPUT_SHIPPER_COST)
    contract_rows = load_csv(INPUT_CONTRACT_TERMS)
    adjustment_rows = load_csv(INPUT_NETWORK_ADJUSTMENTS)
    override_rows = load_csv(INPUT_LAB_CAPACITY_OVERRIDES)
    holdouts = load_json(INPUT_HOLDOUTS)
    template = load_json(INPUT_REPORT_TEMPLATE)

    all_panels = as_panel_list(manifest)
    excluded_codes = {
        row.get("panel_code")
        for row in as_holdout_list(holdouts)
        if row.get("holdout_state") == "exclude"
    }
    retained_panels = [
        panel
        for panel in all_panels
        if panel.get("analysis_mode") == "review"
        and panel.get("panel_code") not in excluded_codes
    ]

    adjustment_by_tier = {
        row["network_tier"]: float(row["network_adjustment_per_run_per_lab_usd"])
        for row in adjustment_rows
    }

    latest_override_by_code = {}
    for row in override_rows:
        if (
            row.get("approval") == "approved"
            and is_not_blank(row.get("rev"))
            and is_not_blank(row.get("active_labs"))
        ):
            code = row.get("panel_code")
            rev = float(row["rev"])
            current = latest_override_by_code.get(code)
            if current is None or rev > float(current["rev"]):
                latest_override_by_code[code] = row

    shipper_cost_by_class = {
        row["shipper_class"]: float(row["shipper_cost_usd"])
        for row in shipper_rows
    }

    panel_outputs = []
    total_margin_14 = 0.0
    total_margin_28 = 0.0

    for panel in retained_panels:
        aliases = set(panel.get("alias_labels", []))
        panel_refs = aliases | {panel.get("panel_name")}
        matching_contracts = [
            row
            for row in contract_rows
            if row.get("status_flag") == "current" and row.get("panel_ref") in panel_refs
        ]
        if not matching_contracts:
            raise ValueError(f"No current contract terms found for {panel['panel_code']}")
        contract = max(matching_contracts, key=lambda row: effective_key(row.get("effective_week", "")))
        base_payment = float(contract["base_payment_per_run_per_lab_usd"])
        network_adjustment = adjustment_by_tier.get(panel.get("network_tier"), 0.0)
        total_payment = base_payment + network_adjustment

        override = latest_override_by_code.get(panel.get("panel_code"))
        active_labs = int(override["active_labs"]) if override else int(panel["default_active_labs"])
        shipper_cost = shipper_cost_by_class[panel["shipper_class"]]
        reagent_cost_per_1000 = float(panel["reagent_cost_per_1000_tests_usd"])

        def model_values(runs_per_year, tests_per_lab_per_run):
            annual_revenue = total_payment * active_labs * runs_per_year
            annual_reagent_cost = (
                reagent_cost_per_1000
                * active_labs
                * tests_per_lab_per_run
                * runs_per_year
                / 1000.0
            )
            annual_shipper_cost = shipper_cost * runs_per_year
            annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
            return {
                "runs_per_year": runs_per_year,
                "tests_per_lab_per_run": int(tests_per_lab_per_run),
                "annual_revenue_usd": currency(annual_revenue),
                "annual_reagent_cost_usd": currency(annual_reagent_cost),
                "annual_shipper_cost_usd": currency(annual_shipper_cost),
                "annual_margin_usd": currency(annual_margin),
            }, annual_margin

        model_14, margin_14 = model_values(26, panel["tests_per_lab_per_run_14_day"])
        model_28, margin_28 = model_values(13, panel["tests_per_lab_per_run_28_day"])
        diff = margin_28 - margin_14
        total_margin_14 += margin_14
        total_margin_28 += margin_28

        panel_outputs.append(
            {
                "panel_code": panel["panel_code"],
                "panel_name": panel["panel_name"],
                "active_labs": active_labs,
                "base_payment_per_run_per_lab_usd": currency(base_payment),
                "network_adjustment_per_run_per_lab_usd": currency(network_adjustment),
                "total_payment_per_run_per_lab_usd": currency(total_payment),
                "shipper_cost_usd": currency(shipper_cost),
                "model_14_day": model_14,
                "model_28_day": model_28,
                "annual_margin_difference_28_minus_14_usd": currency(diff),
            }
        )

    panel_outputs.sort(key=lambda row: row["panel_code"])

    total_diff = total_margin_28 - total_margin_14
    abs_total_diff = abs(total_diff)
    decision = "adopt_28_day" if abs_total_diff < 6000 else "keep_14_day"
    comparison = "below" if abs_total_diff < 6000 else "at or above"
    justification = (
        f"Absolute margin difference of ${abs_total_diff:,.2f} is {comparison} "
        f"the $6,000 threshold; recommend {decision}."
    )

    report = deepcopy(template)
    report["analysis"]["assumptions"] = {
        "runs_per_year_14_day": 26,
        "runs_per_year_28_day": 13,
        "switch_threshold_usd": 6000,
        "override_rule": "Use the approved lab capacity override with the highest numeric rev and nonblank active_labs; otherwise use default_active_labs from the manifest.",
        "holdout_rule": "Retain panels where analysis_mode is review, excluding holdouts where holdout_state is exclude.",
        "adjustment_rule": "Add the network adjustment for the panel network_tier to the base payment; missing network tiers use 0.0.",
    }
    report["analysis"]["panels"] = panel_outputs
    report["analysis"]["totals"] = {
        "total_annual_margin_14_day_usd": currency(total_margin_14),
        "total_annual_margin_28_day_usd": currency(total_margin_28),
        "total_annual_margin_difference_28_minus_14_usd": currency(total_diff),
        "absolute_total_margin_difference_usd": currency(abs_total_diff),
    }
    report["analysis"]["recommendation"] = {
        "decision": decision,
        "justification": justification,
    }

    with open(OUTPUT_REPORT, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, cls=CurrencyEncoder)
        f.write("\n")

    summary_lines = [
        "# Diagnostic Panel Policy Summary",
        f"Total 14-day annual margin: ${total_margin_14:,.2f}",
        f"Total 28-day annual margin: ${total_margin_28:,.2f}",
        f"Absolute margin difference: ${abs_total_diff:,.2f}",
        f"Final decision: {decision}",
    ]
    with open(OUTPUT_SUMMARY, "w", encoding="utf-8") as f:
        f.write("\n".join(summary_lines) + "\n")


if __name__ == "__main__":
    main()

